import urllib.request, xml.etree.ElementTree as ET, re, html
feeds=[('HN','https://hnrss.org/frontpage'),('MarketWatch','https://feeds.content.dowjones.io/public/rss/mw_topstories'),('Google AI','https://blog.google/technology/ai/rss/'),('GitHub','https://github.blog/feed/'),('Vercel','https://vercel.com/changelog/rss')]
for name,url in feeds:
 print('\n##',name)
 try:
  data=urllib.request.urlopen(url,timeout=15).read()
  root=ET.fromstring(data)
  # RSS
  items=root.findall('.//item')
  if items:
   for it in items[:6]:
    title=html.unescape(re.sub('<.*?>','',it.findtext('title','')).strip())
    pub=it.findtext('pubDate','')
    desc=html.unescape(re.sub('<.*?>','',it.findtext('description','')).strip()).replace('\n',' ')[:220]
    print('-',title,'|',pub,'|',desc)
  else:
   ns={'a':'http://www.w3.org/2005/Atom'}
   for e in root.findall('.//a:entry',ns)[:6]:
    title=e.findtext('a:title','',ns); upd=e.findtext('a:updated','',ns)
    cont=''.join(e.find('a:content',ns).itertext()) if e.find('a:content',ns) is not None else ''
    print('-',html.unescape(title),'|',upd,'|',re.sub(r'\s+',' ',cont)[:220])
 except Exception as e: print('ERR',e)
PY","timeout":60}

